// The reported layout was generated by the real Atom/2/SPROUT/2 hotkey.
#include "keymap_data.hpp"
// Atom/2 turns the EXISTING terminal carbon into CHO, retaining its identity.
{
    auto resetAldehyde=[&](){s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.refresh();};
    size_t carbonylKey=0;while(carbonylKey<sizeof(keymap::hotkeys)/sizeof(keymap::hotkeys[0])&&!(std::string(keymap::hotkeys[carbonylKey].command)=="SPROUT"&&std::string(keymap::hotkeys[carbonylKey].value)=="2"))++carbonylKey;
    require(carbonylKey<sizeof(keymap::hotkeys)/sizeof(keymap::hotkeys[0]),"native carbonyl shortcut present");
    auto sprout=[&](ObjectId anchor){s.refresh();auto view=s.view();view.center=s.doc.atoms().get(anchor)->position;view.scale=2;s.setView(view);auto p=s.view().toDevice(s.doc.atoms().get(anchor)->position);SendMessageW(canvas,WM_MOUSEMOVE,0,MAKELPARAM(int(p.x),int(p.y)));editorHotkey(int(carbonylKey));};
    auto angleAt=[&](ObjectId parent,ObjectId carbon,ObjectId oxygen){auto p=s.doc.atoms().get(parent)->position,c=s.doc.atoms().get(carbon)->position,o=s.doc.atoms().get(oxygen)->position;Vec2 v=p-c,w=o-c;return std::acos(std::max(-1.,std::min(1.,dot(v,w)/length(v)/length(w))))*180/3.141592653589793;};
    auto carbonCount=[](const Document& doc){size_t count=0;for(const auto& a:doc.atoms().records())if(a.isAlive()&&a.element==6)++count;return count;};
    for(int rotation=0;rotation<360;rotation+=15){
        resetAldehyde();double radians=rotation*3.141592653589793/180;Vec2 root(30,-20),parent=root+Vec2(-std::cos(radians),std::sin(radians))*14.4;
        ObjectId anchor,tail,bond;s.doc.addAtom(root,6,&anchor);s.doc.addAtom(parent,6,&tail);s.doc.addBond(tail,anchor,&bond);s.refresh();auto before=s.doc.digest();sprout(anchor);
        require(s.doc.stats().aliveAtoms==3&&s.doc.stats().aliveBonds==2&&carbonCount(s.doc)==2,"terminal Atom/2 adds only oxygen and retains the carbon count");
        require(s.doc.atoms().get(anchor)->element==6&&s.doc.atoms().get(2)->element==8,"existing terminal carbon becomes the carbonyl carbon");
        auto carbonyl=s.doc.bonds().get(1);require(carbonyl->beginAtom==anchor&&carbonyl->endAtom==2&&carbonyl->order==BondOrder::Double,"oxygen is double bonded directly to the hotspot carbon");
        require(std::abs(angleAt(tail,anchor,2)-120)<1e-6,"O=C-C angle remains 120 degrees");
        require(length(s.doc.atoms().get(anchor)->position-root)<1e-8&&length(s.doc.atoms().get(tail)->position-parent)<1e-8,"carbonyl sprout preserves the existing chain");
        require(std::abs(length(s.doc.atoms().get(2)->position-s.doc.atoms().get(anchor)->position)-14.4)<1e-6,"carbonyl sprout preserves fixed bond length");
        auto inserted=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before,"carbonyl fragment is one undo step");require(s.undo(true).ok()&&s.doc.digest()==inserted,"carbonyl angle survives redo");
    }
    // The same command also retains carbon count for formaldehyde and ketones.
    resetAldehyde();ObjectId isolated;s.doc.addAtom(Vec2(0,0),6,&isolated);sprout(isolated);
    require(carbonCount(s.doc)==1&&s.doc.stats().aliveAtoms==2&&s.doc.bonds().get(0)->order==BondOrder::Double,"isolated carbon plus Atom/2 produces formaldehyde without an extra carbon");
    resetAldehyde();ObjectId center,left,right,edge;s.doc.addAtom(Vec2(0,0),6,&center);s.doc.addAtom(core::direction(150)*14.4,6,&left);s.doc.addAtom(core::direction(30)*14.4,6,&right);s.doc.addBond(center,left,&edge);s.doc.addBond(center,right,&edge);sprout(center);
    require(carbonCount(s.doc)==3&&s.doc.stats().aliveAtoms==4&&s.doc.atoms().get(3)->element==8,"internal carbon plus Atom/2 retains ketone carbon count");
    require(std::abs(angleAt(left,center,3)-120)<1e-6&&std::abs(angleAt(right,center,3)-120)<1e-6,"internal carbonyl retains trigonal geometry");
    // Generated ring/ketone/chain fixture with nine carbons and one oxygen.
    resetAldehyde();for(int i=0;i<10;++i){Vec2 position;if(i<6)position=Vec2(std::cos(i*3.141592653589793/3)*14.4,std::sin(i*3.141592653589793/3)*14.4);else if(i==6)position=Vec2(28.8,-14.4);else if(i==7)position=Vec2(41.2708,7.2);else if(i==8)position=Vec2(28.8,0);else position=Vec2(53.7416,0);ObjectId id;s.doc.addAtom(position,i==6?8:6,&id);}
    ObjectId edgeId;for(int i=0;i<6;++i){s.doc.addBond(i,(i+1)%6,&edgeId);if(i%2==0)s.doc.setBondOrder(edgeId,BondOrder::Double);}s.doc.addBond(0,8,&edgeId);s.doc.addBond(8,6,&edgeId);s.doc.setBondOrder(edgeId,BondOrder::Double);s.doc.addBond(8,7,&edgeId);s.doc.addBond(7,9,&edgeId);
    s.refresh();auto before=s.doc.digest();std::vector<Vec2> originalPositions;for(ObjectId id=0;id<10;++id)originalPositions.push_back(s.doc.atoms().get(id)->position);require(carbonCount(s.doc)==9,"reported parent has nine carbons");sprout(9);
    require(s.doc.stats().aliveAtoms==11&&s.doc.stats().aliveBonds==11&&carbonCount(s.doc)==9,"reported terminal hotkey retains nine carbons and adds only oxygen");require(std::abs(angleAt(7,9,10)-120)<1e-6,"reported aldehyde has native trigonal angle at the original terminal carbon");
    for(ObjectId id=0;id<10;++id){require(length(s.doc.atoms().get(id)->position-originalPositions[id])<1e-8,"reported original atoms stay in place");require(length(s.doc.atoms().get(10)->position-s.doc.atoms().get(id)->position)>s.doc.defaultBondLength()*.8,"aldehyde oxygen does not overlap an existing atom");}
    require(s.save(testOut+"/reported_same_carbon_aldehyde.cdxml",true).ok(),"save same carbon count aldehyde");s.fit();screenshot(testOut+"/reported_same_carbon_aldehyde.png",false,false);
    Session reopened;require(reopened.open(testOut+"/reported_same_carbon_aldehyde.cdxml").ok(),"reopen same carbon count aldehyde");
    require(reopened.doc.stats().aliveAtoms==11&&reopened.doc.stats().aliveBonds==11&&carbonCount(reopened.doc)==9,"same carbon count and connectivity survive CDXML roundtrip");
    require(s.undo().ok()&&s.doc.digest()==before,"undo corrected reported sprout");
    std::ofstream(testOut+"/aldehyde_angle_tests.json")<<"{\"hotkey\":\"Atom/2/SPROUT/2\",\"rotations\":24,\"O_C_C_degrees\":120,\"carbon_count_unchanged\":true,\"only_oxygen_added\":true,\"terminal_carbon_id_preserved\":true,\"isolated_carbon\":true,\"internal_carbon\":true,\"reported_layout\":true,\"collision_avoidance\":true,\"original_chain_unchanged\":true,\"single_undo\":true,\"redo\":true,\"save_reload\":true}";
    resetAldehyde();
}
